// The published sample documents (public/reference/*.html), generated by scripts/build-reference.sh. One list, so the sitemap, the
// /reference page and the tests that read the files cannot disagree about which documents exist. tests/site/reference-pages.test.ts
// fails when this list and the directory differ, in either direction.
//
// Each page is the canonical copy of its Markdown twin where one exists (the walkthrough deck has none).

export const REFERENCE_DOCUMENTS = [
  "density_screen",
  "proposal",
  "envelope_study",
  "board_summary",
  "walkthrough",
  "specification",
] as const;

export type ReferenceDocument = (typeof REFERENCE_DOCUMENTS)[number];

/** The path of a sample document's canonical (HTML) page. */
export function referencePath(name: ReferenceDocument): string {
  return `/reference/${name}.html`;
}
